def rearange_string(s):
  char_count = {}
  for char in s:
    if char in char_count:
      char_count[char] += 1
    else:
      char_count[char] = 1
  odd_count = sum(1 for count in char_count.values() if count % 2 != 0)
  if odd_count > 1:
    return ""
  sorted_chars = sorted(char_count.items(), key=lambda x: x[1])
  result = []
  for char, count in sorted_chars:
    while count > 0:
      result.append(char)
      result.append(char)
      count -= 2
  return ''.join(result)

