  decreasing = [1]*n

  for i in range(1,n):
      if arr[i]>arr[i-1]:
          increasing[i]=increasing[i-1]+1

  for i in range(n-2,-1,-1):
      if arr[i]>arr[i+1]:
          decreasing[i]=decreasing[i+1]+1

  max_sum = 0
  for i in range(n):
      max_sum = max(max_sum,increasing[i]+decreasing[i]-1)

  return max_sum

